WITH deduped AS (SELECT id, device_code, reading_ts, temp_c, pressure, firmware FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY temp_c, id) AS row_num FROM device_readings) x WHERE row_num = 1) SELECT CASE WHEN pressure >= 1017 THEN 'LARGE' ELSE 'SMALL' END AS pressure_tier, APPROX_PERCENTILE(pressure, 0.5) AS pressure_p50, STDDEV_SAMP(temp_c) AS temp_c_stddev FROM deduped GROUP BY CASE WHEN pressure >= 1017 THEN 'LARGE' ELSE 'SMALL' END ORDER BY pressure_tier;
